-- HALO: check that migration 0028 is applied correctly. Read only.
-- Generated by scripts/build-apply-bundle.mjs from each migration's own verification query.
-- Expect one row: all_migrations_ok = true and failing = none.

with checks as (
  select '0028' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select bool_and(relrowsecurity) from pg_class
          where oid in ('public.household_attachments'::regclass, 'public.attachment_object_sweep'::regclass)) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public' and tablename in ('household_attachments', 'attachment_object_sweep')) = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           cross join unnest(array['public.household_attachments', 'public.attachment_object_sweep']) as t
           where has_any_column_privilege(r, t, 'SELECT') or has_any_column_privilege(r, t, 'INSERT')
              or has_any_column_privilege(r, t, 'UPDATE') or has_table_privilege(r, t, 'DELETE'))
          as no_client_access,
        not exists (
          select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           cross join unnest(array['anon', 'authenticated']) as r
           where n.nspname = 'public' and has_function_privilege(r, p.oid, 'EXECUTE')
             and p.proname in ('household_attachment_json', 'read_household_attachment', 'household_attachment_usage',
                               'check_attachment_references', 'reserve_attachment_object', 'commit_household_attachment',
                               'remove_household_attachment', 'guard_settled_attachments_operation',
                               'link_workspace_attachments', 'delete_record_attachments', 'queue_attachment_object',
                               'clear_attachments_with_privacy_clear', 'attachment_privacy_counts',
                               'expire_staged_attachments', 'due_attachment_objects', 'forget_attachment_objects',
                               'attachment_storage_state'))
          as functions_not_client,
        (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
          where n.nspname = 'public' and not p.prosecdef and 'search_path=public' = any (p.proconfig)
            and p.proname in ('household_attachment_json', 'read_household_attachment', 'household_attachment_usage',
                              'check_attachment_references', 'reserve_attachment_object', 'commit_household_attachment',
                              'remove_household_attachment', 'guard_settled_attachments_operation',
                              'link_workspace_attachments', 'delete_record_attachments', 'queue_attachment_object',
                              'clear_attachments_with_privacy_clear', 'attachment_privacy_counts',
                              'expire_staged_attachments', 'due_attachment_objects', 'forget_attachment_objects',
                              'attachment_storage_state')) = 17
          as functions_invoker_pinned,
        (select count(*) from pg_trigger
          where tgname in ('operations_attachments_settled_guard', 'operations_privacy_clear_attachments',
                           'household_workspace_records_link_attachments', 'household_workspace_records_delete_attachments',
                           'household_attachments_queue_object')) = 5
          as triggers_on,
        (public.attachment_storage_state() ->> 'storage' = 'false'
          or (public.attachment_storage_state() ->> 'bucket' = 'true'
              and public.attachment_storage_state() ->> 'private' = 'true'))
          as bucket_private,
        (public.attachment_storage_state() ->> 'policies') = '0'
          as no_bucket_policy
  ) q, jsonb_each_text(to_jsonb(q)) j
)
select bool_and(ok) as all_migrations_ok,
       count(*) as checks_run,
       coalesce(string_agg(migration || '.' || check_name, ', ') filter (where not ok), 'none') as failing
from checks;
